"""V6-specific UI, without obsolete storage stations and dimensions."""
def prepare(d,structure,tabs,downloads):
    cards=''.join(f'<article class="card level-card"><h3>{l["label"]}</h3><p>Y {l["y"][0]}–{l["y"][1]} · {l["positions"]:,} Baupositionen</p><button class="mini" data-level-cut="{l["y"][1]}">Schnitt in 3D öffnen</button></article>' for l in d['structure']['levels'])
    structure='<section class="tab" id="tab-structure"><div class="page-intro"><h2>Version 6 · Euer gebauter Keller als Grundlage</h2><p>Schachbrettboden auf Y 95 und Außenwände bis Y 126 bleiben Grundlage; das Haus beginnt auf Y 127. Untere Nebenräume, ein freigeräumter Lagerbereich und eine freie Porter-Galerie ersetzen die alten Kelleretagen.</p></div><div class="floor-grid">'+cards+'</div><div class="card"><h3>Gesamte Nordwand für eure Porter</h3><p>X −709…−659 · Z 767…780 · Boden Y 121. Fünf Blöcke Raumhöhe über dem Boden; keine Möbel oder Schaltungen im Reservestreifen. Farbige Bodenlinien zeigen Chunkgrenzen. Perlenkammer, Auslöser und Verkabelung jedes Porters innerhalb eines passenden Chunks platzieren.</p><p>Die Vorlagen für eure bereits gebauten Porter sind nicht Bestandteil des Hausmodells. Auch die automatische Erkennung zählt den freien Ausbauplatz nicht als fertig gebaute Porterschaltung.</p></div><div class="card"><h3>Zugang und geheimer Abstieg</h3><p>Der südöstliche Leiterzugang bei X −661 / Z 803 verbindet Boden Y 95, Reserve Y 101 und Y 107, Lager Y 113, Galerie Y 121 und EG Y 127. Eine zweite Leiter in der neuen Nische außerhalb der Westwand führt bei X −712 / Z 776 zum Gang auf Y 80. Drei Blöcke Kopfraum im unteren Gang sind freigehalten.</p><a href="umbau_v6.md" class="btn" download>Umbaufolge und Prüfgrenzen herunterladen</a></div></section>'
    system='<section class="tab" id="tab-system"><div class="page-intro"><h2>Neues Lager und Kellerhöhen</h2><p>Das bisherige Dustless-Lager ist aus dem Hausmodell, den Baupositionen und den Materialmengen entfernt. Die Originaldateien bleiben als Vorlagen erhalten.</p></div><div class="card"><h3>Fünf Kelleretagen · Lagerfläche frei</h3><p>Von oben nach unten: fünf, sieben, fünf, fünf und fünf Blöcke freie Raumhöhe. Das neue Lager soll in die zweite Kelleretage von oben. Seine Schaltung und Grundfläche sind noch nicht Bestandteil des Bauplans.</p><p>Der vorhandene Boden bleibt auf Y 95. Das Haus steht jetzt mit EG-Boden auf Y 127. Alle Geschossböden sind einen Block dick. Das neue Lager erhält Boden Y 113 und freie Höhe Y 114–120.</p><a class="btn" href="keller_hoehenplanung.md">Höhen und Etagen vergleichen</a></div><div class="notice"><p>Die neuen Geschossböden sind im Modell enthalten. Leiter und Wasserzugang verbinden alle fünf Kelleretagen. Das neue Lager ist noch nicht eingebaut; die freie Fläche zählt nicht als fertige Schaltung.</p></div></section>'
    tabs['material']=tabs['material'].replace('Einrichtung und originale Lager-Litematics haben separate Materiallisten.','Das bisherige Großlager ist entfernt. Material für das neue Lager ist noch nicht enthalten.')
    tabs['material']=tabs['material'].replace('Ausführlicher Prüfbericht</a>', 'Ausführlicher Prüfbericht</a> · <a href="materialbedarf_keller_zusaetzlich.csv" download>Zusatzmaterial Keller gegenüber eurem Bestand</a>')
    tabs['storage']=tabs['storage'].replace('50 Regallagerbuchten und sechs Privatreserven. Kategorien durchsuchen, Bestände notieren und die Position im Ebenenplan öffnen.','Fünf Reservefässer im unteren Keller. Notizen bleiben lokal; gemeinsame Materialmengen stehen unter Organisation → Gemeinsame Liste. Die Planung für das neue Lager findet ihr unter Sortierung & Technik.').replace('lager_regale','v6_handlager').replace('Regallager in 3D','Reservefässer in 3D')
    tabs['terrain']=tabs['terrain'].replace('<div class="earth-summary">','<div class="notice"><b>V6-Keller nach aktuellem Bestand</b><p>Die globale Höhenkarte beruht auf dem älteren Weltstand. Für euren Keller sind die aktuelle Umbau- und Freiraumliste maßgeblich.</p><a href="keller_umbau_6.0.csv" download>Keller-Umbau gegenüber Bestand</a> · <a href="freiraeume_6.0.csv" download>V6-Freiraumliste</a></div><div class="earth-summary">')
    structure=structure.replace('<div class="floor-grid">','<a class="outdoor-image" href="assets/keller_v6.png"><img src="assets/keller_v6.png" alt="Fünf Kellerschnitte mit Chunkgrenzen und freier Nordwand" loading="lazy"></a><div class="floor-grid">')
    structure=structure.replace('<div class="floor-grid">','<div class="row"><button class="btn primary" data-cellar-floor>Vorhandenen Kellerboden in 3D ansehen</button><button class="btn" data-tab="plan">Ebenenplan öffnen</button></div><div class="notice"><p>In der Zielansicht wird die alte Geländehaut innerhalb des Kellers ausgespart. Die Ansicht „Historisches Originalgelände“ zeigt weiterhin den früheren Weltstand.</p></div><div class="floor-grid">')
    tabs['3d']=tabs['3d'].replace('>Originalgelände</option>','>Historisches Originalgelände</option>')
    structure=structure.replace('</section>', '<div class="card"><h3>Pool und Garten</h3><p>Ruhige Poolterrasse, breiter flacher Einstieg, Unterwasserlicht und Sitzplätze. Im Südgarten ergänzt eine offene Pergola die Rosenterrasse.</p><div class="row"><button class="btn" data-v6-outdoor="pool">Pool in 3D ansehen</button><button class="btn" data-v6-outdoor="garden">Südgarten in 3D ansehen</button><a class="btn" href="assets/aussen_v6.png">Außenanlagen im Blockplan</a><a class="btn" href="aussenanlagen_v6.md" download>Umbauhinweise für Pool und Garten</a></div></div></section>')
    structure=structure.replace('</section>','<div class="card"><h3>Wasserzugänge und Geheimsalon</h3><p>Zwei getrennte Zugänge verbinden Haus und Keller sowie Keller und tiefen Geheimgang. Jeweils links führt die Blasensäule nach oben, rechts der Fallschacht mit Wasserlandung nach unten. Hauszugang: X −669 / −667, Z 801. Tiefer Zugang: X −714 / −712, Z 779. Der bestehende Kellerboden auf Y 95 bleibt vollständig erhalten.</p><p>Der neue Geheimsalon am Gang besitzt 15 × 14 Blöcke Innenfläche und sieben Blöcke Raumhöhe. Bestehende Haupttreppe und Leiterzugänge bleiben vorhanden. Wasserstopp-Schilder und alle Säulen vor Nutzung im Spiel prüfen.</p><div class="row"><button class="btn" data-v6-water="house">Hauszugang in 3D</button><button class="btn" data-v6-water="secret">Tiefen Zugang in 3D</button><button class="btn" data-v6-water="room">Geheimsalon öffnen</button><a class="btn" href="wasserwege_v6.md" download>Bau- und Bedienhinweise</a></div></div></section>')
    review=d['structure'].get('v6',{}).get('refinement')
    if review:
        lighting=review['lighting']
        summary='<div class="card"><span class="eyebrow">GEMEINSAME ÜBERARBEITUNG</span><h3>Licht, Garten, Pferdestall und Flussaussicht</h3><p>Der fertige Kellerboden Y 95, die fünf Kelleretagen und der EG-Boden Y 127 bleiben erhalten. Die neue Lagerfläche bleibt frei.</p><a class="outdoor-image" href="assets/ausbau_v6.png"><img src="assets/ausbau_v6.png" alt="Koordinatengenaue Schnitte durch Pferdestall, Dachlesesaal und Flussgalerie" loading="lazy"></a>'
        if review.get('terrain_clearance'):
            sx0,sx1,_,_,sz0,sz1=review['architecture']['stable_bounds']
            summary+='<div class="notice"><b>Haus und Zufahrt freigehalten</b><p>Die Geländedarstellung liegt jetzt unter den gebauten Böden. Der Stall steht neben der Hauptzufahrt bei X '+str(sx0)+'…'+str(sx1)+' / Z '+str(sz0)+'…'+str(sz1)+'. Die ursprünglichen 489 Zufahrtblöcke sind wiederhergestellt; ein eigener Seitenweg erschließt den Stall.</p><a href="freiraumkorrektur_v6.md">Korrektur und Prüfergebnisse</a></div>'
        if review.get('terrain_blend'):
            blend=review['terrain_blend']
            summary+='<div class="notice"><b>Sanfter Plateauanschluss und geschlossene Erdseiten</b><p>'+str(blend['softened_columns'])+' Randspalten weich abgestuft; im Übergangsband wird nur abgetragen. Die kleine Westfundamentlücke wird separat unterfüttert. Der Boden unter den Hausflügeln bleibt auch in der Kelleransicht geschlossen. Nur die echte Kellerhöhlung und die Zugänge sind ausgespart; ihre Erdseiten bleiben sichtbar.</p><a href="terrain_anschluss_v6.md">Bauhinweise und Prüfumfang</a></div>'
        summary+='<div class="task-grid">'
        details=[('Licht ohne Hindernisse',str(lighting['removed_floor_lanterns'])+' störende Bodenlaternen ersetzt; kurze, verankerte Dekorleuchten bleiben. Verdeckte Quellen und die neue Giebelbeleuchtung sind statisch geprüft.','facade','beleuchtung_v6.md'),('Garten und Gelände','Weiche Grasübergänge, geordnete Beete, verdecktes Heckenlicht und freie Wege. Die Zieloberfläche liegt wieder unter den Pflanzen.','garden','garten_gelaende_v6.md'),('Pferdestall','Zwei Boxen, dreibreiter Mittelgang, drei Torflügel und eine angepasste Rampe. Vor dem Ausreiten alle Torflügel öffnen.','stable','architektur_v6.md'),('Dachgiebel nutzen','Westlicher Lesesaal auf Boden Y 143 mit Zugang von der Nordgalerie. Bücher, Kartentisch und Sitzplatz stehen hinter der erhaltenen Giebelfront.','roof','architektur_v6.md'),('Flussgalerie aus Keller 3','Boden Y 107; überdachter Gang unter der Poolterrasse bis zur geschlossenen Panorama-Verglasung bei X −629.','river','flussloggia_v6.md'),('Außenstruktur','Dunkler Sockel, gezielte Steinprofile und Kupferakzente ordnen die viktorianische Fassade. Fenster und Haupttreppe bleiben erhalten.','facade','architektur_v6.md')]
        for title,text,view,document in details:
            summary+='<article class="card"><h4>'+title+'</h4><p>'+text+'</p><div class="row"><button class="btn" data-v6-refinement="'+view+'">In 3D ansehen</button><a class="btn" href="'+document+'">Bauhinweise</a></div></article>'
        summary+='</div><p class="muted">Blocklicht und Durchgänge sind statisch geprüft. Pferde mit Reiter, Torbedienung, Wasser und das tatsächliche Spawnverhalten bitte im Spiel abnehmen.</p><a href="ausbau_pruefung_v6.json" download>Prüfbericht herunterladen</a> · <a href="gelaende_aktuell_v6.csv" download>Aktuelle Geländeoberflächen</a></div>'
        structure=structure.replace('<div class="floor-grid">',summary+'<div class="floor-grid">',1)
        tabs['overview']=tabs['overview'].replace('</section>','<div class="card"><h2>Neu am Anwesen</h2><p>Überarbeitete Beleuchtung und Gartenwege, zwei große Pferdeboxen, ein Lesesaal im Westgiebel und eine Flussgalerie aus Keller 3.</p><button class="btn primary" data-tab="structure">Neue Bereiche im Bauatlas öffnen</button></div></section>',1)
        tabs['terrain']=tabs['terrain'].replace('<div class="earth-summary">','<div class="notice"><b>Oberflächen und unterirdische Arbeiten getrennt lesen</b><p>Die aktuellen Zielhöhen und Gartenspalten sind abgeglichen. Unter Haus, Pool und gebauten Wegen bezeichnet die Zielhöhe das Gelände unter den tatsächlichen Baublöcken; die Bauhöhe darüber steht in der Blockliste. Der globale Ausgangsscan ist historisch. Der neue unterirdische Gang zur Flussloggia verändert die Oberfläche nicht; seinen Aushub zeigt die Freiraumliste, nicht das Höhenprofil.</p><a href="flussloggia_v6.md">Flussgalerie bauen</a> · <a href="freiraeume_6.0.csv" download>Freiraumliste</a></div><div class="earth-summary">',1)
        tabs['terrain']=tabs['terrain'].replace('href="terraforming.csv"','href="gelaende_aktuell_v6.csv"').replace('href="terraforming_chunks.csv"','href="gelaende_chunks_v6.csv"')
    categories=[('Gemeinsame Überarbeitung',[('terrain_anschluss_v6.md','Plateauanschluss und Keller-Erdseiten'),('freiraumkorrektur_v6.md','Haus und Zufahrt freihalten'),('ausbau_v6.md','Überblick über alle Verbesserungen'),('assets/ausbau_v6.png','Neue Bauteile im Blockplan'),('beleuchtung_v6.md','Beleuchtung und Prüfgrenzen'),('garten_gelaende_v6.md','Garten und Gelände'),('architektur_v6.md','Pferdestall und Dachlesesaal'),('flussloggia_v6.md','Flussaussicht aus Keller 3'),('ausbau_pruefung_v6.json','Statische Ausbauprüfungen'),('gelaende_aktuell_v6.csv','Aktuelle Geländeoberflächen'),('gelaende_chunks_v6.csv','Aktuelle Geländeabschnitte')]),('Bauen und Material',[('blockliste.csv','Alle Baupositionen'),('blackthorn_estate_6.0.nbt','Hausmodell V6 · NBT ohne Inventare'),('materialbedarf.csv','Gesamtmaterial ohne entferntes Großlager'),('materialbedarf_haus.csv','Haus und Keller'),('materialbedarf_aussenanlagen.csv','Außenanlagen'),('materialbedarf_gelaende.csv','Gelände'),('materialpruefung.md','Materialprüfung')]),('Kellerumbau',[('umbau_v6.md','Umbaufolge und Grenzen'),('keller_umbau_6.0.csv','Änderungen gegenüber eurem Kellerbestand'),('materialbedarf_keller_zusaetzlich.csv','Zusatzmaterial im vermessenen Keller'),('freiraeume_6.0.csv','Freizuhaltende Positionen'),('keller_hoehenplanung.md','Neue Kellerhöhen · Planung'),('assets/keller_v6.png','Kellerschnitte mit Chunkraster'),('aenderungen_5.26_zu_6.0.csv','Modelländerungen 5.26 → V6')]),('Live und gemeinsames Bauen',[('downloads/BlackthornLive.jar','Paper-Plugin 1.4.0 mit V6-Plan'),('live_fortschritt.md','Live-Plugin installieren'),('gemeinsame_liste.md','Gemeinsame Materialliste einrichten')]),('Globales Gelände · älterer Weltstand',[('terraforming.csv','Globale Ist-/Soll-Spalten'),('terraforming_chunks.csv','Globale Chunk-Arbeiten'),('assets/terraforming_vergleich.png','Globaler Geländevergleich')])]
    downloads='<section class="tab" id="tab-downloads"><div class="page-intro"><h2>Version 6 · Dateien für euren Bau</h2><p>Das alte Großlager wurde entfernt; das neue Lager ist noch nicht enthalten. Für den aktuellen Kellerbestand die V6-Umbau- und Zusatzmaterialliste verwenden. Globale Geländekarten beruhen weiterhin auf dem älteren Weltstand.</p></div><div class="download-grid">'+''.join('<article class="card"><h3>'+title+'</h3><ul class="file-list">'+''.join('<li><a href="'+file+'" download><span>'+label+'</span><small>'+file.rsplit('.',1)[-1].upper()+' ↓</small></a></li>' for file,label in files)+'</ul></article>' for title,files in categories)+'</div></section>'
    return structure,system,downloads
